import type { Mesa } from "./recepcion";
import type { Menu } from "./menu";

export enum EstadoComanda {
  PENDIENTE = 0,
  EN_COCINA = 1,
  LISTO = 2,
  CANCELADO = 3,
}

export interface DetalleComanda {
  id_menu: string;
  menu: Menu;
  cantidad: number;
  observacion?: string;
}

export interface Comanda {
  id_comanda: string;
  mesa: Mesa;
  hora: string;
  estado: EstadoComanda;
  detalles: DetalleComanda[];
}
