import { Comanda, EstadoComanda } from "@/types/comandas";
import Badge from "@/components/ui/badge";
import Card from "@/components/ui/card";
import Button from "@/components/ui/button";

interface ComandaCardProps {
  comanda: Comanda;
  onAceptar: () => void;
  onTransferir: () => void;
  onVerDetalle: () => void;
  onMarcarLista: () => void;
}

export const ESTADO_COMANDA_LABEL: Record<EstadoComanda, string> = {
  [EstadoComanda.PENDIENTE]: "Pendiente",
  [EstadoComanda.EN_COCINA]: "En cocina",
  [EstadoComanda.LISTO]: "Listo",
  [EstadoComanda.CANCELADO]: "Cancelado",
};

export default function ComandaCard({
  comanda,
  onAceptar,
  onTransferir,
  onVerDetalle,
  onMarcarLista,
}: ComandaCardProps) {
  const badgeVariants: Record<
    string,
    "success" | "default" | "warning" | "info"
  > = {
    [EstadoComanda.PENDIENTE]: "warning",
    [EstadoComanda.EN_COCINA]: "info",
    [EstadoComanda.LISTO]: "success",
    [EstadoComanda.CANCELADO]: "default",
  };

  // Función para formatear la fecha y hora
  const formatFechaHora = (fecha: string) =>
    new Date(fecha).toLocaleDateString("es-PE") +
    " " +
    new Date(fecha).toLocaleTimeString("es-PE", {
      hour: "2-digit",
      minute: "2-digit",
    });

  return (
    <Card className="h-full flex flex-col bg-white border border-gray-300 rounded-lg p-4 shadow-md text-sm ">
      <div className="flex-1 space-y-4">
        {/* HEADER */}
        <div className="flex justify-between items-center border-b border-gray-400 pb-2">
          <div>
            <p className="font-bold text-base">
              Comanda Mesa {comanda.mesa.id}
            </p>
            <p className="text-xs text-gray-500">
              {formatFechaHora(comanda.hora)}
            </p>
          </div>

          <Badge variant={badgeVariants[comanda.estado]}>
            {ESTADO_COMANDA_LABEL[comanda.estado]}
          </Badge>
        </div>

        {/* PLATILLOS */}
        <div>
          <div className="flex justify-between font-bold border-b border-gray-300 pb-1 text-sm">
            <span>Cant.</span>
            <span>Platillos</span>
          </div>

          {comanda.detalles
            .filter((d) => d.menu.tipo === "Plato")
            .map((d) => (
              <div
                key={d.id_menu}
                className="flex justify-between py-1 text-sm"
              >
                <span className="font-semibold">{d.cantidad}</span>

                <span className="text-right flex-1 ml-3">
                  {d.menu.nombre}
                  {d.observacion && (
                    <p className="text-xs italic text-gray-500 mt-0.5">
                      {d.observacion}
                    </p>
                  )}
                </span>
              </div>
            ))}
        </div>
      </div>

      {/* BEBIDAS */}
      <div>
        <div className="flex justify-between font-bold border-b border-gray-300 pb-1 text-sm">
          <span>Cant.</span>
          <span>Bebidas</span>
        </div>

        {comanda.detalles
          .filter((d) => d.menu.tipo === "Bebida")
          .map((d) => (
            <div key={d.id_menu} className="flex justify-between py-1 text-sm">
              <span className="font-semibold">{d.cantidad}</span>
              <span className="text-right flex-1 ml-3">{d.menu.nombre}</span>
            </div>
          ))}
      </div>

      {/* POSTRES */}
      <div>
        <div className="flex justify-between font-bold border-b border-gray-300 pb-1 text-sm">
          <span>Cant.</span>
          <span>Postres</span>
        </div>

        {comanda.detalles
          .filter((d) => d.menu.tipo === "Postre")
          .map((d) => (
            <div key={d.id_menu} className="flex justify-between py-1 text-sm">
              <span className="font-semibold">{d.cantidad}</span>
              <span className="text-right flex-1 ml-3">{d.menu.nombre}</span>
            </div>
          ))}
      </div>

      {/* FOOTER */}
      <div className="border-t border-gray-400 pt-2 text-xs text-gray-600">
        <p>
          Mesa: {comanda.mesa.nombre} · {comanda.mesa.capacidad} pers
        </p>
        <p>Ubicación: {comanda.mesa.ubicacion}</p>
      </div>

      {/* ACCIONES */}
      <div className="flex justify-center gap-5 pt-2">
        {/* ESTADO: pendiente */}
        {comanda.estado === 0 && (
          <>
            <Button variant="primary" className="w-full" onClick={onAceptar}>
              Aceptar
            </Button>

            <Button
              variant="secondary"
              className="w-full"
              onClick={onTransferir}
            >
              Transferir
            </Button>
          </>
        )}

        {/* ESTADO: en_cocina */}
        {comanda.estado === 1 && (
          <>
            <Button
              variant="primary"
              className="w-full"
              onClick={onMarcarLista}
            >
              Comanda lista
            </Button>

            <Button
              variant="secondary"
              className="w-full"
              onClick={onVerDetalle}
            >
              Ver comanda
            </Button>
          </>
        )}

        {/* ESTADO: listo y cancelado */}
        {(comanda.estado === 2 || comanda.estado === 3) && (
          <Button variant="secondary" className="w-full" onClick={onVerDetalle}>
            Ver comanda
          </Button>
        )}
      </div>
    </Card>
  );
}
