"use client";

import { useState } from "react";
import { EstadoComanda } from "@/types/comandas";

type Opcion = { label: string; value: EstadoComanda };

type Props = {
  opciones?: Opcion[];
  onChange: (estado: EstadoComanda) => void;
};

function FiltroComandas({ opciones, onChange }: Props) {
  const [activo, setActivo] = useState<EstadoComanda>(
    opciones?.[0]?.value ?? EstadoComanda.EN_COCINA,
  );

  const handleClick = (estado: EstadoComanda) => {
    setActivo(estado);
    onChange(estado);
  };

  return (
    <div className="flex w-full justify-start">
      <div className="flex gap-2 bg-gray-200 px-2 py-1 rounded-xl shadow-md">
        {opciones?.map((o) => (
          <button
            key={o.value}
            onClick={() => handleClick(o.value)}
            className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all duration-200
              ${activo === o.value ? "bg-blue-600 text-white shadow" : "bg-gray-100 text-gray-700 hover:bg-gray-300"}`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export default FiltroComandas;
